/**
 * Positions indexed by group (e.g. doggy, missionary, oral). Each entry includes positionNumber so description and image (position N.png) stay mapped.
 * Use for organization and editing by group. Lookups by position number still use PHASE3_POSITIONS_LIST[positionNumber].
 */
function buildPhase3PositionsByGroup() {
  const byGroup = {};
  for (let i = 1; i <= PHASE3_POSITION_COUNT; i++) {
    const entry = PHASE3_POSITIONS_LIST[i];
    if (!entry) continue;
    const g = entry.group || 'other';
    if (!byGroup[g]) byGroup[g] = [];
    byGroup[g].push({ ...entry, positionNumber: i });
  }
  return byGroup;
}
const PHASE3_POSITIONS_BY_GROUP = buildPhase3PositionsByGroup();

/** Positions with anal and rearEntryVaginalEase === 'hard' (parallel, e.g. reverse missionary) are rerolled when "Include anal / rear-entry" is off. */
function getPhase3AnalOrientedPositionNumbers() {
  return PHASE3_POSITIONS_LIST
    .map((entry, i) => (i >= 1 && entry && entry.anal && entry.rearEntryVaginalEase === 'hard' ? i : 0))
    .filter(n => n > 0);
}
PHASE3_ANAL_POSITION_NUMBERS = getPhase3AnalOrientedPositionNumbers();

function getPhase3PositionsForTable() {
  const positions = {};
  for (let n = 1; n <= PHASE3_POSITION_COUNT; n++) {
    const entry = PHASE3_POSITIONS_LIST[n];
    if (entry) positions[n] = entry.description;
  }
  return positions;
}

/**
 * Scrub hetero-specific position names to neutral alternatives
 */
function scrubHeteroPositionName(name) {
  if (!name || typeof name !== 'string') return name;
  return name
    .replace(/\bstraddle\b/gi, 'Straddle')
    .replace(/\breverse straddle\b/gi, 'Reverse straddle')
    .replace(/\bdoggy\b/gi, 'Rear entry')
    .replace(/\bdoggy style\b/gi, 'Rear entry style');
}

function getPhase3PositionName(positionNumber) {
  const n = parseInt(positionNumber, 10);
  if (n < 1 || n > PHASE3_POSITION_COUNT) return '';
  const pos = PHASE3_POSITIONS_LIST[n];
  if (!pos) return '';
  return scrubHeteroPositionName(pos.name);
}

